/**
 * @name Unsafe string formatting
 * @description Using % or format() with untrusted input
 * @kind path-problem
 * @problem.severity warning
 * @id py/unsafe-string-format-jsonschema
 * @tags security
 *        external/cwe/cwe-134
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources

module UnsafeFormatConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(BinaryExpr binop |
      binop.getOp() instanceof Mod and
      sink.asExpr() = binop.getRight()
    )
  }
}

module UnsafeFormatFlow = TaintTracking::Global<UnsafeFormatConfig>;
import UnsafeFormatFlow::PathGraph

from UnsafeFormatFlow::PathNode source, UnsafeFormatFlow::PathNode sink
where UnsafeFormatFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe string formatting from $@.", source.getNode(), "user input"

/**
 * @name Uncontrolled data in exception message
 * @description Including untrusted data in exception messages
 * @kind path-problem
 * @problem.severity warning
 * @id py/uncontrolled-exception-message-jsonschema
 * @tags security
 *        external/cwe/cwe-209
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking

module ExceptionMessageConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(Raise raise, Call call |
      call = raise.getException() and
      sink.asExpr() = call.getAnArg()
    )
  }
}

module ExceptionMessageFlow = TaintTracking::Global<ExceptionMessageConfig>;
import ExceptionMessageFlow::PathGraph

from ExceptionMessageFlow::PathNode source, ExceptionMessageFlow::PathNode sink
where ExceptionMessageFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Exception message includes untrusted data from $@.", source.getNode(), "parameter"
